#!/usr/bin/env python3
"""Create a CSV containing the first attendee row for each email address."""

import csv

INPUT_FILE = "attendees.csv"
OUTPUT_FILE = "attendees_clean.csv"


def main():
    with open(INPUT_FILE, "r", encoding="utf-8", newline="") as source, open(
        OUTPUT_FILE, "w", encoding="utf-8", newline=""
    ) as destination:
        reader = csv.reader(source)
        writer = csv.writer(destination, lineterminator="\n")

        header = next(reader, None)
        if header is None:
            return
        writer.writerow(header)

        try:
            email_column = header.index("email")
        except ValueError:
            raise ValueError("attendees.csv has no email column")

        seen_emails = set()
        for row in reader:
            # Preserve rows without an email field; malformed rows cannot
            # represent a duplicate email.
            if len(row) <= email_column:
                writer.writerow(row)
                continue
            email = row[email_column]
            if email not in seen_emails:
                seen_emails.add(email)
                writer.writerow(row)


if __name__ == "__main__":
    main()
